export interface ApiEndpoint {
  method: "GET" | "POST" | "PUT" | "DELETE";
  path: string;
  owner: "Shopkeeper" | "Dashboard";
  title: string;
  description: string;
  auth: string;
  body?: string;
  query?: string;
  exampleQuery?: string;
  bearerKey?: boolean;
  response: string;
  notes?: string[];
}

export interface ApiGroup {
  title: string;
  description: string;
  endpoints: ApiEndpoint[];
}

